 describe("adaptEventsToTraceFormat", () => {
+  it("preserves latency and tags for a historical REST trace", () => {
+    const result = adaptEventsToTraceFormat({
+      events: [
+        createEvent({
+          id: "rest-observation-12736",
+          traceId: historicalRestTrace.traceId,
+          startTime: new Date(historicalRestTrace.startTime),
+          endTime: new Date(historicalRestTrace.endTime),
+          tags: historicalRestTrace.tags,
+          traceTags: [],
+        }),
+      ],
+      traceId: historicalRestTrace.traceId,
+    });
+
+    expect(result.trace.latency).toBe(4.25);
+    expect(result.trace.tags).toEqual(["rest", "historical"]);
+  });
+
+  it("continues to prefer OpenTelemetry trace tags", () => {
+    const result = adaptEventsToTraceFormat({
+      events: [
+        createEvent({
+          tags: ["observation"],
+          traceTags: ["otel", "production"],
+        }),
+      ],
+      traceId: "trace-1",
+    });
+
+    expect(result.trace.tags).toEqual(["otel", "production"]);
+  });
